import{_ as a,g as t,e as s,a4 as i}from"./chunks/framework.CEYJDsBW.js";const b=JSON.parse('{"title":"In-Game Guide and Dynamic Models","description":"","frontmatter":{},"headers":[],"relativePath":"en/anvilcraft/21.1/packs/resources/guide.md","filePath":"en/anvilcraft/21.1/packs/resources/guide.md"}'),n={name:"en/anvilcraft/21.1/packs/resources/guide.md"};function r(l,e,d,c,o,m){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="in-game-guide-and-dynamic-models" tabindex="-1">In-Game Guide and Dynamic Models <a class="header-anchor" href="#in-game-guide-and-dynamic-models" aria-label="Permalink to &quot;In-Game Guide and Dynamic Models&quot;">​</a></h1><p>The guide lives at <code>assets/anvilcraft/ageratum/&lt;language&gt;/&lt;category&gt;/&lt;article&gt;.md</code>. Resource packs can modify existing articles using the same path. Keep the YAML front matter navigation title and icon; the body can display current recipes via Ageratum&#39;s item reference and recipe components. Chinese articles use <code>zh_cn</code>.</p><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/resources/assets/anvilcraft/ageratum/zh_cn/000_process/001.md" target="_blank" rel="noreferrer">Bundled Chinese guide article</a></p><h2 id="intermediate-states-and-celestial-models" tabindex="-1">Intermediate States and Celestial Models <a class="header-anchor" href="#intermediate-states-and-celestial-models" aria-label="Permalink to &quot;Intermediate States and Celestial Models&quot;">​</a></h2><p>The client collects JSON models under <code>models/block/wip_display/</code> for sequential assembly and <code>models/block/celestial_body/</code> for celestial bodies, registering them as standalone models. <code>displayed_models</code> in sequential assembly uses model IDs without <code>models/</code> or the file extension. Celestial textures live in <code>assets/anvilcraft/textures/block/celestial_body/</code>; reloading resource packs clears the dynamic texture cache.</p><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/client/event/RegisterAdditionalEventListener.java" target="_blank" rel="noreferrer">RegisterAdditionalEventListener.java</a> · <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/client/event/StellarVisualReloadListener.java" target="_blank" rel="noreferrer">StellarVisualReloadListener.java</a></p>',6)])])}const h=a(n,[["render",r]]);export{b as __pageData,h as default};
